<body>
<div id="game-container">
    <canvas id="gameCanvas" width="400" height="600"></canvas>
    <div class="ui-overlay" id="scoreDisplay">Score: <span id="score">0</span></div>
    <div class="game-over" id="gameOverScreen">
        GAME OVER!
        <button class="btn btn-play" onclick="startGame()">PLAY AGAIN</button>
    </div>
</div>

<script>
(function() {
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');
    const scoreEl = document.getElementById('score');
    const gameOverScreen = document.getElementById('gameOverScreen');

    // Game state
    let gameState = 'START'; // START, PLAYING, GAMEOVER
    let score = 0;
    let frames = 0;

    // Bird
    const bird = {
        x: 50, y: 200, width: 34, height: 24, velocity: 0, gravity: 0.5, jump: -8, rotation: 0
    };

    // Pipes configuration
    const pipeWidth = 50;
    const pipeGap = 150;
    const pipeFrequency = 100;
    let pipes = [];

    // Draw background
    function drawBackground() {
        ctx.fillStyle = '#87CEEB';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Clouds
        ctx.fillStyle = 'rgba(255,255,255,0.6)';
        for(let i=0; i<3; i++) {
            ctx.beginPath();
            let cx = (100 + 150*i) % (canvas.width + 200) - 100;
            ctx.arc(cx, 80 + Math.sin(frames * 0.01 + i)*20, 30, 0, Math.PI*2);
            ctx.arc(cx+25, 70 + Math.sin(frames * 0.01 + i)*15, 35, 0, Math.PI*2);
            ctx.arc(cx+50, 80 + Math.sin(frames * 0.01 + i)*20, 30, 0, Math.PI*2);
            ctx.fill();
        }
    }

    // Draw city skyline silhouette
    function drawCity() {
        ctx.fillStyle = '#2D4A3E';
        const buildings = [
            {x:0,h:150}, {x:40,h:180}, {x:80,h:160}, {x:130,h:200}, 
            {x:180,h:170}, {x:220,h:190}, {x:260,h:150}, {x:310,h:180}
        ];
        ctx.fillStyle = '#3A5F4F';
        for(let b of buildings) {
            ctx.fillRect(b.x, 600-b.h, 40, b.h);
        }
    }

    // Draw ground
    function drawGround() {
        ctx.fillStyle = '#C89E4D';
        ctx.fillRect(0, canvas.height - 20, canvas.width, 20);

        // Moving pattern
        ctx.strokeStyle = '#8B6F35';
        ctx.lineWidth = 2;
        for(let i=-canvas.width; i<canvas.width*2; i+=40) {
            let offset = (frames * 3) % 40;
            ctx.beginPath();
            ctx.moveTo(i - offset + 10, canvas.height - 20);
            ctx.lineTo(i - offset + 50, canvas.height - 20);
            ctx.stroke();
        }
    }

    // Draw bird
    function drawBird() {
        ctx.save();
        ctx.translate(bird.x + bird.width/2, bird.y + bird.height/2);
        ctx.rotate(bird.rotation);

        // Bird body (yellow)
        ctx.fillStyle = '#FFD700';
        ctx.beginPath();
        ctx.ellipse(0, 0, 17, 12, 0, 0, Math.PI * 2);
        ctx.fill();

        // Wing (white)
        ctx.fillStyle = '#FFFFFF';
        ctx.beginPath();
        ctx.ellipse(-5, 3, 8, 6, -0.3, 0, Math.PI * 2);
        ctx.fill();

        // Eye (white with black pupil)
        ctx.fillStyle = 'white';
        ctx.beginPath();
        ctx.arc(8, -4, 4, 0, Math.PI*2);
        ctx.fill();

        ctx.fillStyle = 'black';
        ctx.beginPath();
        ctx.arc(9, -4, 1.5, 0, Math.PI*2);
        ctx.fill();

        // Beak (orange)
        ctx.fillStyle = '#FFA500';
        ctx.beginPath();
        ctx.moveTo(10, -2);
        ctx.lineTo(18, 0);
        ctx.lineTo(10, 3);
        ctx.fill();

        ctx.restore();
    }

    // Draw pipes
    function drawPipes() {
        for(let pipe of pipes) {
            const gradient = createPipeGradient();

            // Top pipe
            ctx.fillStyle = '#228B22';
            ctx.fillRect(pipe.x, 0, pipeWidth, pipe.top);

            // Pipe cap top
            ctx.fillStyle = '#32CD32';
            ctx.fillRect(pipe.x - 3, pipe.top - 25, pipeWidth + 6, 25);

            // Bottom pipe
            ctx.fillStyle = '#228B22';
            ctx.fillRect(pipe.x, canvas.height - pipe.bottom, pipeWidth, pipe.bottom);

            // Pipe cap bottom
            ctx.fillStyle = '#32CD32';
            ctx.fillRect(pipe.x - 3, canvas.height - pipe.bottom, pipeWidth + 6, 25);
        }
    }

    function createPipeGradient() {
        const gradient = ctx.createLinearGradient(0, 0, pipeWidth, 0);
        gradient.addColorStop(0, '#1B5E20');
        gradient.addColorStop(0.3, '#228B22');
        gradient.addColorStop(0.7, '#2ECC71');
        gradient.addColorStop(1, '#1B5E20');
        return gradient;
    }

    // Spawn new pipe
    function spawnPipe() {
        const minHeight = 50;
        const maxHeight = canvas.height - pipeGap - 50;
        const topHeight = Math.floor(Math.random() * (maxHeight - minHeight + 1) + minHeight);

        pipes.push({
            x: canvas.width,
            top: topHeight,
            bottom: canvas.height - pipeGap - topHeight,
            passed: false
        });
    }

    // Update bird physics
    function updateBird() {
        bird.velocity += bird.gravity;
        bird.y += bird.velocity;

        // Rotation based on velocity
        bird.rotation = Math.min(Math.PI / 4, Math.max(-Math.PI / 4, (bird.velocity * 0.1)));

        // Collision with ground
        if(bird.y + bird.height >= canvas.height - 20) {
            bird.y = canvas.height - 20 - bird.height;
            gameOver();
        }
    }

    // Check pipe collisions
    function checkPipesCollision() {
        for(let pipe of pipes) {
            if(bird.x + bird.width > pipe.x && bird.x < pipe.x + pipeWidth) {
                // Hit top pipe OR hit bottom pipe
                if(bird.y < pipe.top || bird.y + bird.height > canvas.height - pipe.bottom) {
                    gameOver();
                }
            }

            // Score when passing pipe
            if(pipe.x + pipeWidth < bird.x && !pipe.passed) {
                score++;
                scoreEl.textContent = score;
                pipe.passed = true;
            }
        }
    }

    // Update pipes array
    function updatePipes() {
        // Remove off-screen pipes
        pipes = pipes.filter(pipe => pipe.x > -pipeWidth);

        // Spawn new pipe periodically
        if(frames % pipeFrequency === 0) {
            spawnPipe();
        }
    }

    // Main game loop
    function update() {
        frames++;
        drawBackground();
        drawCity();

        if(gameState === 'PLAYING') {
            updateBird();
            checkPipesCollision();
            drawBird();
            drawPipes();
            drawGround();
            updatePipes();
            checkGameOver();
        }
    }

    function checkGameOver() {
        if(pipes.length > 0 && pipes[pipes.length-1].x < -pipeWidth * 2) {
            gameOver();
        }
    }

    function gameOver() {
        gameState = 'GAMEOVER';
        gameOverScreen.style.display = 'block';
    }

    // Draw initial screen
    function drawStartScreen() {
        ctx.fillStyle = '#FFF';
        ctx.font = 'bold 28px Courier New';
        ctx.textAlign = 'center';
        ctx.fillText('FLAPPY BIRD', canvas.width/2, 150);

        ctx.font = '18px Courier New';
        ctx.fillText('Click or press SPACE to flap', canvas.width/2, 300);
        ctx.fillText('Don\'t hit the pipes!', canvas.width/2, 340);
    }

    // Main render function
    function draw() {
        if(gameState === 'START') {
            drawStartScreen();
            updatePipes();
        } else if (gameState === 'GAMEOVER') {
            ctx.fillStyle = 'rgba(255,0,0,0.3)';
            ctx.font = 'bold 48px Courier New';
            ctx.textAlign = 'center';
            ctx.fillText('GAME OVER', canvas.width/2, 150);
        } else {
            drawBackground();
            drawCity();
            if(pipes.length > 0 || frames % pipeFrequency === 0) {
                pipes.push({x: canvas.width, top: 50, bottom: canvas.height - 150 - 50});
            }
        }

        // Always draw bird (except start screen for simplicity)
        if(gameState !== 'START') {
            drawBird();
            drawGround();
        }
    }

    // Game loop interval
    setInterval(function() {
        update();
        draw();
    }, 1000/60);

    // Jump on click/space
    function jump() {
        if(gameState === 'START') {
            gameState = 'PLAYING';
            gameOverScreen.style.display = 'none';
        } else if(gameState === 'PLAYING') {
            bird.velocity = bird.jump;
        }
    }

    canvas.addEventListener('click', jump);
    document.addEventListener('keydown', function(e) {
        if(e.code === 'Space') jump();
    });

    // Initial draw
    draw();
})();
</script>
</body>
</html>
