<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Particle Wave Simulation</title>
    <style>
        * { margin: 0; padding: 0; }
        body {
            background: #0a0a0f;
            display: flex;
            justify-content: center;
            align-items: center;
