            font-size: 14px;
            font-weight: bold;
            background: linear-gradient(135deg, #0066cc, #00ccff);
            color: white;
        }
        .btn:hover { transform: scale(1.05); }
    </style>
</head>
<body>
<canvas id="canvas"></canvas>
<div class="controls">
    <button class="btn" onclick="reset()">RESET</button>
    <button class="btn" onclick="togglePause()" id="pauseBtn">PAUSE</button>
    <label style="color:#fff;font-weight:bold;margin-left:15px;">Particles:</label>
    <input type="range" min="50" max="500" value="200" id="countSlider" oninput="updateCount()">
</div>

<script>
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
let width, height;

// Setup canvas size
function resize() {
    width = Math.min(window.innerWidth - 40, 900);
    height = Math.min(window.innerHeight - 150, 600);
    canvas.width = width;
    canvas.height = height;
}
resize();

// Particles array
let particles = [];
let mouse = { x: null, y: null };

class Particle {
    constructor() {
        this.reset(true);
    }

    reset(randomStart = false) {
        this.x = randomStart ? Math.random() * width : width/2;
        this.y = randomStart ? height/2 : Math.random() * height;
        this.size = 3 + Math.random() * 4;
        this.baseSize = this.size;
        this.vx = (Math.random() - 0.5) * (2 + Math.random() * 1);
        this.vy = (Math.random() - 0.5) * (2 + Math.random() * 1);
        this.life = 1;
        this.maxLife = 1 + Math.random() * 0.5;
        this.colorHue = Math.random() * 360;
    }

    update() {
        // Natural movement
        this.x += this.vx;
        this.y += this.vy;

        // Mouse interaction
        if(mouse.x !== null) {
            const dx = mouse.x - this.x;
            const dy = mouse.y - this.y;
            const dist = Math.sqrt(dx*dx + dy*dy);

            if(dist < 200) {
                this.x += dx * 0.02;
                this.y += dy * 0.02;
            }
        }

        // Return to center attraction
        const centerX = width/2 + Math.sin(Date.now() * 0.001) * 50;
        const centerY = height/2 + Math.cos(Date.now() * 0.001) * 30;

        this.vx += (centerX - this.x) * 0.005;
        this.vy += (centerY - this.y) * 0.005;

        // Friction
        this.vx *= 0.98;
        this.vy *= 0.98;

        // Decay life slowly for continuous effect
        this.life = Math.max(0, this.life + 0.01);
    }

    draw() {
        const x = this.x + Math.sin(Date.now() * 0.003) * 5;
        const y = this.y + Math.cos(Date.now() * 0.003 + this.colorHue/180) * 5;

        ctx.beginPath();
        ctx.arc(x, y, this.size * this.life, 0, Math.PI * 2);
        ctx.fillStyle = `hsla(${this.colorHue + Date.now()/10}, 70%, 60%, ${0.6 * this.life})`;
        ctx.fill();
    }
}

let particleCount = parseInt(document.getElementById('countSlider').value);
function initParticles() {
    particles = [];
    for(let i=0; i<particleCount; i++) {
        particles.push(new Particle());
    }
}
initParticles();

function updateCount() {
    particleCount = parseInt(document.getElementById('countSlider').value);
    if(particles.length !== particleCount) {
        initParticles();
    }
}

document.addEventListener('mousemove', e => {
    mouse.x = e.clientX;
    mouse.y = e.clientY;
});

function animate() {
    // Clear with trail effect
    ctx.fillStyle = 'rgba(10, 10, 15, 0.2)';
    ctx.fillRect(0, 0, width, height);

    // Draw connecting lines between nearby particles
    if(particles.length > 30 && Math.random() > 0.7) {
        for(let i=0; i<particles.length-1; i++) {
            for(let j=i+1; j<particles.length; j++) {
                const dx = particles[i].x - particles[j].x;
                const dy = particles[i].y - particles[j].y;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if(dist < 150) {
                    ctx.beginPath();
                    ctx.moveTo(particles[i].x, particles[i].y);
                    ctx.lineTo(particles[j].x, particles[j].y);
                    ctx.strokeStyle = `rgba(0, 184, 255, ${0.2 * (1 - dist/150)})`;
                    ctx.stroke();
                }
            }
        }
    }

    // Draw and update particles
    particles.forEach(p => {
        p.update();
        p.draw();
    });

    requestAnimationFrame(animate);
}

function reset() {
    initParticles();
}

function togglePause() {
    const btn = document.getElementById('pauseBtn');
    if(canvas.style.animation === 'none') {
        canvas.style.animation = 'pulse 2s infinite';
    } else {
        canvas.style.animation = 'none';
    }
}

animate();
</script>
</body>
</html>
