        ctx.beginPath();
        ctx.moveTo(10, -2);
        ctx.lineTo(18, 0);
        ctx.lineTo(10, 3);
        ctx.fill();

        ctx.restore();

        ctx.fillStyle = '#ded895';
        ctx.fillRect(0, canvas.height - 15, canvas.width, 15);
    } else {
        gameOverScreen.classList.remove('hidden');
        finalScoreEl.textContent = score;
    }

    requestAnimationFrame(draw);
}

function createGradient(c1, c2) {
    const g = ctx.createLinearGradient(0, 0, pipeWidth, 0);
    g.addColorStop(0, c1);
    g.addColorStop(0.5, c2);
    g.addColorStop(1, c1);
    return g;
}

function spawnPipe() {
    const minHeight = 60;
    const maxHeight = canvas.height - pipeGap - minHeight - 20;
    const topHeight = Math.floor(Math.random() * (maxHeight - minHeight + 1) + minHeight);

    pipes.push({
        x: canvas.width,
        top: topHeight,
        bottom: canvas.height - pipeGap - topHeight,
        passed: false
    });
}

function updateBird() {
    bird.velocity += bird.gravity;
    bird.y += bird.velocity;

    if(bird.y + bird.height >= canvas.height - 15) {
        bird.y = canvas.height - 15 - bird.height;
        gameOver();
    }
}

function checkPipesCollision() {
    for(let pipe of pipes) {
        if(bird.x + bird.width > pipe.x && bird.x < pipe.x + pipeWidth) {
            if(bird.y < pipe.top || bird.y + bird.height > canvas.height - pipe.bottom) {
                gameOver();
            }
        }

        if(pipe.x + pipeWidth < bird.x && !pipe.passed) {
            score++;
            scoreDisplay.textContent = score;
            pipe.passed = true;
        }
    }
}

function updatePipes() {
    pipes = pipes.filter(pipe => pipe.x > -pipeWidth);

    if(frames % pipeFrequency === 0) {
        spawnPipe();
    }
}

function gameOver() {
    gameState = 'GAMEOVER';
}

function jump() {
    if(gameState === 'START') {
        gameState = 'PLAYING';
        startScreen.classList.add('hidden');
    } else if(gameState === 'PLAYING') {
        bird.velocity = bird.jump;
    }
}

function startGame() {
    gameState = 'PLAYING';
    startScreen.classList.add('hidden');
}

function restartGame() {
    bird.y = 250;
    bird.velocity = 0;
    pipes = [];
    score = 0;
    frames = 0;
    scoreDisplay.textContent = '0';

    startScreen.classList.add('hidden');
    gameOverScreen.classList.add('hidden');

    gameState = 'PLAYING';
}

canvas.addEventListener('click', jump);
document.addEventListener('keydown', function(e) {
    if(e.code === 'Space') jump();
});

requestAnimationFrame(draw);

function animatePhysics() {
    requestAnimationFrame(animatePhysics);

    if(gameState === 'PLAYING') {
        frames++;
        updateBird();
        checkPipesCollision();
        updatePipes();
    }
}
animatePhysics();
</script>
</body>
